import { ParentComponent } from "solid-js";

import { CardFrame } from "#core/ui-next/components/card-frame.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import { ScienceDetailStarInfo } from "#base/ui-next/screens/victories/victories-screen-model.js";

const ScienceVictoryItemTooltipComponent: ParentComponent<ScienceDetailStarInfo> = (props) => {
	return (
		<Tooltip>
			<Tooltip.Trigger>{props.children}</Tooltip.Trigger>
			<Tooltip.Content>
				<Tooltip.Frame class="relative flex flex-col items-center min-w-64 max-w-96">
					<div class="uppercase text-secondary font-title">
						<L10n.Compose
							text="LOC_VICTORIES_ITEM_TOOLTIP_AGE"
							args={[props.ageName]}
						/>
					</div>
					<div class="uppercase mb-3">
						<L10n.Stylize
							text="LOC_VICTORIES_ITEM_TOOLTIP_TURN"
							args={[props.turn]}
						/>
					</div>
					<CardFrame class="w-full p-4">
						<div class="flex flex-row">
							<div class="flex-auto font-body mr-2 self-center">
								<L10n.Compose text={props.description} />
							</div>
							<div class="text-white self-center">{props.pointsValue}</div>
						</div>
					</CardFrame>
				</Tooltip.Frame>
			</Tooltip.Content>
		</Tooltip>
	);
};

export const ScienceVictoryItemTooltip = ComponentRegistry.register({
	name: "ScienceVictoryItemTooltip",
	createInstance: ScienceVictoryItemTooltipComponent,
});
